<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
type Character={name:string;owner:string;class:string;level:number;color?:string;status?:string}
type Dashboard={activePlayers:number;totalLevels:number;deaths:number;playedHours:number;characters:Character[];events:{title:string;detail:string;type?:string}[]}
const route=ref(location.hash.slice(1)||"overview"), menu=ref(false), connected=ref(false), loading=ref(true), now=ref(Date.now())
const data=ref<Dashboard>({activePlayers:0,totalLevels:0,deaths:0,playedHours:0,characters:[],events:[]})
const pages=[['overview','OVERVIEW'],['crew','THE CREW'],['characters','CHARACTERS'],['chronicle','CHRONICLE']]
const title=computed(()=>pages.find(p=>p[0]===route.value)?.[1]||'OVERVIEW')
function navigate(to:string){route.value=to;menu.value=false;location.hash=to}
onMounted(async()=>{addEventListener('hashchange',()=>route.value=location.hash.slice(1)||'overview');try{const r=await fetch('/api/dashboard');if(r.ok)data.value=await r.json()}finally{loading.value=false}})
const launchAt=new Date("2026-11-05T00:00:00+01:00").getTime()
const countdown=computed(()=>{const s=Math.max(0,Math.floor((launchAt-now.value)/1000));return {days:Math.floor(s/86400),hours:Math.floor(s%86400/3600),minutes:Math.floor(s%3600/60),seconds:s%60}})
setInterval(()=>now.value=Date.now(),1000)
</script>
<template><div class="app-shell"><header class="topbar"><button class="mobile-menu" @click="menu=!menu">☰</button><div class="brand" @click="navigate('overview')"><div class="brand-mark">✦</div><div><b>CZECHDREAM</b><span>FOREVER</span></div></div><nav :class="{open:menu}"><a v-for="page in pages" :key="page[0]" :class="{selected:route===page[0]}" @click="navigate(page[0])">{{page[1]}}</a></nav><div class="top-actions"><span class="public-badge">PUBLIC GUILD DASHBOARD</span></div></header><main><section v-if="route==='overview'" class="launch-banner"><div><div class="kicker"><i></i> WORLD OF WARCRAFT: FOREVER</div><h2>THE JOURNEY BEGINS</h2><p>Global launch · 5 November 2026 · 00:00 CET</p></div><div class="countdown"><div><strong>{{String(countdown.days).padStart(2,'0')}}</strong><small>DAYS</small></div><b>:</b><div><strong>{{String(countdown.hours).padStart(2,'0')}}</strong><small>HOURS</small></div><b>:</b><div><strong>{{String(countdown.minutes).padStart(2,'0')}}</strong><small>MIN</small></div><b>:</b><div><strong>{{String(countdown.seconds).padStart(2,'0')}}</strong><small>SEC</small></div></div></section><section v-if="route==='overview'" class="hero"><div class="hero-copy"><div class="kicker"><i></i> THE CZECHDREAM GUILD</div><h1>ZBYTOČNÍ<br><em>SÚ SPÄŤ.</em></h1><p>A shared chronicle of every level, death, victory and ridiculous moment in Azeroth.</p><div class="hero-buttons"><button class="gold-button" @click="connected=!connected">{{connected?'BRIDGE CONNECTED':'CONNECT YOUR BRIDGE'}} <span>→</span></button><button class="ghost-button" @click="navigate('chronicle')">VIEW CHRONICLE</button></div></div><div class="hero-art"><div class="moon"></div><div class="mountain">⚔</div><div class="hero-tag"><strong>SEASON ONE</strong><span>THE JOURNEY BEGINS</span></div></div></section><section class="section-head"><div><div class="kicker">GUILD INTELLIGENCE</div><h2>{{title}}</h2></div><div class="live"><i></i>{{connected?'BRIDGE ONLINE':'AWAITING SYNC'}}</div></section><section v-if="route==='overview'" class="stats"><article><span class="stat-icon">♙</span><div><small>ACTIVE PLAYERS</small><strong>{{data.activePlayers}}</strong><label>from synced data</label></div></article><article><span class="stat-icon gold">♜</span><div><small>TOTAL LEVELS</small><strong>{{data.totalLevels}}</strong><label>across all characters</label></div></article><article><span class="stat-icon red">☠</span><div><small>DEATHS RECORDED</small><strong>{{data.deaths}}</strong><label>from synced events</label></div></article><article><span class="stat-icon purple">◈</span><div><small>TIME TOGETHER</small><strong>{{data.playedHours}}h</strong><label>from synced sessions</label></div></article></section><section v-if="route==='overview'||route==='crew'||route==='characters'" class="content-grid"><article class="panel wide"><div class="panel-title"><div><div class="kicker">THE PARTY</div><h3>{{route==='crew'?'CREW MEMBERS':'CHARACTER ROSTER'}}</h3></div></div><div class="roster-row header-row"><span>CHARACTER</span><span>CLASS</span><span>LEVEL</span><span>STATUS</span></div><div v-if="loading" class="empty-state">Loading guild data...</div><div v-else-if="!data.characters.length" class="empty-state">No characters synced yet. Connect a CzechDream Bridge.</div><div v-for="player in data.characters" v-else :key="player.name" class="roster-row"><div class="character"><span :class="['portrait',player.color]">{{player.name[0]}}</span><div><b>{{player.name}}</b><small>{{player.owner}}</small></div></div><span class="class-name">{{player.class}}</span><b class="level">{{player.level}}</b><span :class="['player-status',player.status]"><i></i>{{player.status}}</span></div></article><article v-if="route==='overview'" class="panel"><div class="panel-title"><div><div class="kicker">RECENT MOMENTS</div><h3>THE CHRONICLE</h3></div></div><div v-if="!data.events.length" class="empty-state">No events synced yet.</div><div v-else class="timeline"><div v-for="event in data.events.slice(0,5)" :key="event.title"><span class="event-icon death">✦</span><p><b>{{event.title}}</b><small>{{event.detail}}</small></p></div></div></article></section><section v-if="route==='chronicle'" class="panel chronicle-page"><div class="panel-title"><div><div class="kicker">ALL GUILD EVENTS</div><h3>THE CHRONICLE</h3></div></div><div v-if="!data.events.length" class="empty-state">No events synced yet. Your guild story will appear here.</div><div v-else class="timeline"><div v-for="event in data.events" :key="event.title"><span class="event-icon death">✦</span><p><b>{{event.title}}</b><small>{{event.detail}}</small></p></div></div></section></main><footer><span>© 2026 CZECHDREAM FOREVER</span><span>PUBLIC GUILD CHRONICLE · AZEROTH</span></footer></div></template>
